/* ---------- garden: bouquet builder ---------- */
const FL = { rose: ['ورد جوري', 'Rose'], peony: ['فاوانيا', 'Peony'], tulip: ['توليب', 'Tulip'], lavender: ['لافندر', 'Lavender'], gyp: ['بيبي بريث', "Baby's breath"], euc: ['أوكالبتوس', 'Eucalyptus'] };
const FILLER = ['gyp', 'euc'];
const COL = { blush: ['#E9A3AE', '#C7677B', 'وردي', 'Blush'], cream: ['#FFF0DC', '#D9BC93', 'كريمي', 'Cream'], wine: ['#9A4A62', '#6E2C44', 'نبيذي', 'Wine'], butter: ['#F5D77E', '#C9A241', 'زبدي', 'Butter'], lilac: ['#BBA6DB', '#8A72B5', 'ليلكي', 'Lilac'], peach: ['#F7B393', '#D98462', 'خوخي', 'Peach'] };
